head.script:
//

(function () {
  'use strict';
  var light = window.matchMedia && window.matchMedia('(prefers-color-scheme: light)').matches;
  document.documentElement.setAttribute('data-theme', light ? 'light' : 'dark');
})();

//

head.b:skin:
/* VESTIGIO - Plantilla Blogger - Informatica Forense */


:root {
  --font-body: 'Satoshi', 'Inter', system-ui, -apple-system, sans-serif;
  --font-mono: 'JetBrains Mono', ui-monospace, 'SFMono-Regular', Menlo, monospace;

  --text-xs: clamp(0.75rem, 0.72rem + 0.15vw, 0.8125rem);
  --text-sm: clamp(0.875rem, 0.84rem + 0.2vw, 0.9375rem);
  --text-base: clamp(1rem, 0.96rem + 0.2vw, 1.0625rem);
  --text-lg: clamp(1.125rem, 1.05rem + 0.4vw, 1.3125rem);
  --text-xl: clamp(1.5rem, 1.3rem + 1vw, 2.125rem);
  --text-2xl: clamp(2rem, 1.6rem + 2vw, 3.25rem);
  --text-hero: clamp(2.5rem, 1.7rem + 4vw, 5rem);

  --space-1: 0.25rem; --space-2: 0.5rem; --space-3: 0.75rem; --space-4: 1rem;
  --space-5: 1.25rem; --space-6: 1.5rem; --space-8: 2rem; --space-10: 2.5rem;
  --space-12: 3rem; --space-16: 4rem; --space-20: 5rem; --space-24: 6rem;

  --radius-sm: 4px; --radius-md: 8px; --radius-lg: 14px;
  --container: 1200px;
  --header-h: 72px;
  --ease: cubic-bezier(0.16, 1, 0.3, 1);
  --t-fast: 160ms; --t-med: 320ms;
}


[data-theme='dark'] {
  --bg: #07090d;
  --surface: #0c1016;
  --surface-2: #111722;
  --surface-3: #172030;
  --border: #1d2735;
  --border-strong: #2a3850;
  --text: #dfe6ee;
  --text-muted: #8391a5;
  --text-faint: #56637a;
  --accent: #33e39b;
  --accent-hover: #5cf0b3;
  --accent-ink: #03140c;
  --accent-soft: rgba(51, 227, 155, 0.1);
  --accent-glow: rgba(51, 227, 155, 0.35);
  --danger: #ff6b6b;
  --warn: #ffc857;
  --grid-line: rgba(120, 160, 200, 0.05);
  --matrix-color: 51, 227, 155;
  --shadow: 0 20px 50px -20px rgba(0, 0, 0, 0.7);
  color-scheme: dark;
}


[data-theme='light'] {
  --bg: #f4f6f8;
  --surface: #ffffff;
  --surface-2: #eef1f5;
  --surface-3: #e3e8ee;
  --border: #d9dfe7;
  --border-strong: #bcc6d3;
  --text: #0d1622;
  --text-muted: #4d5b6e;
  --text-faint: #8794a6;
  --accent: #067a50;
  --accent-hover: #045c3c;
  --accent-ink: #ffffff;
  --accent-soft: rgba(6, 122, 80, 0.08);
  --accent-glow: rgba(6, 122, 80, 0.22);
  --danger: #c62828;
  --warn: #9a6700;
  --grid-line: rgba(13, 22, 34, 0.05);
  --matrix-color: 6, 122, 80;
  --shadow: 0 18px 40px -22px rgba(13, 22, 34, 0.25);
  color-scheme: light;
}


*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html {
  scroll-behavior: smooth;
  scroll-padding-top: calc(var(--header-h) + 16px);
  -webkit-text-size-adjust: 100%;
  text-size-adjust: 100%;
}
body {
  font-family: var(--font-body);
  font-size: var(--text-base);
  line-height: 1.6;
  color: var(--text);
  background: var(--bg);
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
  transition: background-color var(--t-med) ease, color var(--t-med) ease;
}
img, svg { display: block; max-width: 100%; }
a { color: inherit; text-decoration: none; }
button, input, select, textarea { font: inherit; color: inherit; }
button { cursor: pointer; background: none; border: 0; }
ul, ol { list-style: none; }
h1, h2, h3 { line-height: 1.1; letter-spacing: -0.02em; font-weight: 700; text-wrap: balance; }
p { text-wrap: pretty; }
::selection { background: var(--accent); color: var(--accent-ink); }
:focus-visible { outline: 2px solid var(--accent); outline-offset: 3px; border-radius: 2px; }

.container { width: min(100% - 2.5rem, var(--container)); margin-inline: auto; }
.mono { font-family: var(--font-mono); }
.muted { color: var(--text-muted); }
.sr-only {
  position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0;
}
.skip-link {
  position: absolute; left: 1rem; top: -100px; z-index: 200;
  background: var(--accent); color: var(--accent-ink);
  padding: 0.6rem 1rem; border-radius: var(--radius-md); font-weight: 700;
}
.skip-link:focus { top: 1rem; }


.bg-grid {
  position: fixed; inset: 0; z-index: -2; pointer-events: none;
  background-image:
    linear-gradient(var(--grid-line) 1px, transparent 1px),
    linear-gradient(90deg, var(--grid-line) 1px, transparent 1px);
  background-size: 48px 48px;
  mask-image: radial-gradient(ellipse at 50% 0%, #000 30%, transparent 75%);
  -webkit-mask-image: radial-gradient(ellipse at 50% 0%, #000 30%, transparent 75%);
}
.bg-matrix {
  position: fixed; inset: 0; z-index: -1; pointer-events: none;
  width: 100%; height: 100%; opacity: 0.16;
  mask-image: linear-gradient(to bottom, #000 0%, transparent 70%);
  -webkit-mask-image: linear-gradient(to bottom, #000 0%, transparent 70%);
}
[data-theme='light'] .bg-matrix { opacity: 0.08; }
[data-theme='light'] .glitch::before, [data-theme='light'] .glitch::after { mix-blend-mode: multiply; }


.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 0.5rem;
  padding: 0.85rem 1.4rem; border-radius: var(--radius-md);
  font-weight: 700; font-size: var(--text-sm); letter-spacing: 0.01em;
  border: 1px solid transparent; white-space: nowrap;
  transition: transform var(--t-fast) var(--ease), background var(--t-fast), box-shadow var(--t-med), border-color var(--t-fast), color var(--t-fast);
}
.btn-primary { background: var(--accent); color: var(--accent-ink); box-shadow: 0 0 0 0 var(--accent-glow); }
.btn-primary:hover { background: var(--accent-hover); box-shadow: 0 8px 30px -6px var(--accent-glow); transform: translateY(-1px); }
.btn-ghost { border-color: var(--border-strong); color: var(--text); background: color-mix(in srgb, var(--surface) 60%, transparent); }
.btn-ghost:hover { border-color: var(--accent); color: var(--accent); }
.btn-sm { padding: 0.55rem 1rem; font-size: var(--text-xs); }
.btn-block { width: 100%; }
.btn:disabled { opacity: 0.45; cursor: not-allowed; transform: none; box-shadow: none; }
.btn:active:not(:disabled) { transform: translateY(0) scale(0.98); }


.site-header {
  position: sticky; top: 0; z-index: 100; height: var(--header-h);
  border-bottom: 1px solid transparent;
  transition: border-color var(--t-med);
}

.site-header::before {
  content: ''; position: absolute; inset: 0; z-index: -1;
  background: color-mix(in srgb, var(--bg) 70%, transparent);
  backdrop-filter: blur(14px) saturate(140%);
  -webkit-backdrop-filter: blur(14px) saturate(140%);
  transition: background var(--t-med);
}
.site-header.scrolled { border-bottom-color: var(--border); }
.site-header.scrolled::before { background: color-mix(in srgb, var(--bg) 88%, transparent); }
.header-inner { height: 100%; display: flex; align-items: center; justify-content: space-between; gap: var(--space-6); }

.brand { display: flex; align-items: center; gap: 0.7rem; color: var(--text); }
.brand-mark { width: 36px; height: 36px; flex-shrink: 0; }
.brand-text { font-family: var(--font-mono); font-weight: 700; font-size: 1.05rem; letter-spacing: 0.12em; line-height: 1.05; display: flex; flex-direction: column; }
.brand-sub { font-size: 0.62rem; font-weight: 400; letter-spacing: 0.22em; color: var(--text-muted); text-transform: uppercase; }

.main-nav { display: flex; align-items: center; gap: var(--space-8); }
.main-nav ul { display: flex; gap: var(--space-6); }
.main-nav ul a {
  font-size: var(--text-sm); color: var(--text-muted); font-weight: 500; position: relative; padding-block: 0.4rem;
  transition: color var(--t-fast);
}
.main-nav ul a::after {
  content: ''; position: absolute; left: 0; bottom: 0; height: 1px; width: 100%;
  background: var(--accent); transform: scaleX(0); transform-origin: left; transition: transform var(--t-med) var(--ease);
}
.main-nav ul a:hover, .main-nav ul a.active { color: var(--text); }
.main-nav ul a:hover::after, .main-nav ul a.active::after { transform: scaleX(1); }

.header-actions { display: flex; align-items: center; gap: var(--space-2); }
.theme-toggle {
  width: 42px; height: 42px; border-radius: var(--radius-md); display: grid; place-items: center;
  border: 1px solid var(--border); color: var(--text-muted); background: var(--surface);
  transition: color var(--t-fast), border-color var(--t-fast), transform var(--t-med) var(--ease);
}
.theme-toggle:hover { color: var(--accent); border-color: var(--accent); }
.theme-toggle svg { width: 19px; height: 19px; grid-area: 1 / 1; transition: transform var(--t-med) var(--ease), opacity var(--t-fast); }
[data-theme='dark'] .icon-moon, [data-theme='light'] .icon-sun { opacity: 0; transform: rotate(-90deg) scale(0.5); }
[data-theme='dark'] .icon-sun, [data-theme='light'] .icon-moon { opacity: 1; transform: none; }

.menu-toggle { display: none; width: 42px; height: 42px; border-radius: var(--radius-md); border: 1px solid var(--border); background: var(--surface); flex-direction: column; align-items: center; justify-content: center; gap: 5px; }
.menu-toggle span { width: 18px; height: 2px; background: var(--text); transition: transform var(--t-med) var(--ease), opacity var(--t-fast); }
.menu-toggle[aria-expanded='true'] span:nth-child(1) { transform: translateY(7px) rotate(45deg); }
.menu-toggle[aria-expanded='true'] span:nth-child(2) { opacity: 0; }
.menu-toggle[aria-expanded='true'] span:nth-child(3) { transform: translateY(-7px) rotate(-45deg); }


.hero { padding-block: clamp(3rem, 8vw, 7rem) var(--space-16); position: relative; }
.hero-inner { display: grid; grid-template-columns: 1.1fr 0.9fr; gap: clamp(2rem, 5vw, 4.5rem); align-items: center; }
.eyebrow {
  display: inline-flex; align-items: center; gap: 0.6rem;
  font-family: var(--font-mono); font-size: var(--text-xs); color: var(--text-muted);
  padding: 0.4rem 0.8rem; border: 1px solid var(--border); border-radius: 999px; background: var(--surface);
  margin-bottom: var(--space-6);
}
.dot { width: 8px; height: 8px; border-radius: 50%; background: var(--accent); box-shadow: 0 0 0 0 var(--accent-glow); animation: pulse 2s infinite; }
@keyframes pulse { 0% { box-shadow: 0 0 0 0 var(--accent-glow); } 70% { box-shadow: 0 0 0 10px transparent; } 100% { box-shadow: 0 0 0 0 transparent; } }

.hero h1 { font-size: var(--text-hero); font-weight: 900; letter-spacing: -0.035em; margin-bottom: var(--space-6); }
.lead { font-size: var(--text-lg); color: var(--text-muted); max-width: 58ch; margin-bottom: var(--space-8); }
.hero-ctas { display: flex; flex-wrap: wrap; gap: var(--space-3); margin-bottom: var(--space-8); }
.hero-badges { display: flex; flex-wrap: wrap; gap: var(--space-2); }
.hero-badges li { font-family: var(--font-mono); font-size: var(--text-xs); color: var(--text-faint); padding: 0.25rem 0.6rem; border: 1px dashed var(--border-strong); border-radius: var(--radius-sm); }

.glitch { position: relative; color: var(--accent); display: inline-block; }
.glitch::before, .glitch::after { content: attr(data-text); position: absolute; inset: 0; opacity: 0; pointer-events: none; }
.glitch::before { color: #ff4d8d; animation: glitch-a 4s infinite steps(1); }
.glitch::after { color: #4dc3ff; animation: glitch-b 4s infinite steps(1); }
@keyframes glitch-a { 0%, 92%, 100% { opacity: 0; transform: none; } 93% { opacity: 0.8; transform: translate(-3px, 1px); clip-path: inset(10% 0 55% 0); } 95% { opacity: 0.8; transform: translate(2px, -1px); clip-path: inset(60% 0 10% 0); } }
@keyframes glitch-b { 0%, 93%, 100% { opacity: 0; transform: none; } 94% { opacity: 0.7; transform: translate(3px, 0); clip-path: inset(40% 0 30% 0); } 96% { opacity: 0.7; transform: translate(-2px, 1px); clip-path: inset(5% 0 75% 0); } }


.terminal {
  background: #05070a; border: 1px solid #1d2735; border-radius: var(--radius-lg);
  box-shadow: var(--shadow), 0 0 0 1px rgba(51, 227, 155, 0.05), 0 0 80px -30px var(--accent-glow);
  overflow: hidden; min-width: 0;
}
.terminal-bar { display: flex; align-items: center; gap: 7px; padding: 0.75rem 1rem; background: #0b0f15; border-bottom: 1px solid #1a2230; }
.tdot { width: 11px; height: 11px; border-radius: 50%; }
.tdot.r { background: #ff5f57; } .tdot.y { background: #febc2e; } .tdot.g { background: #28c840; }
.terminal-title { margin-left: 0.6rem; font-family: var(--font-mono); font-size: 0.72rem; color: #6b7a90; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.terminal-body {
  font-family: var(--font-mono); font-size: clamp(0.68rem, 0.62rem + 0.3vw, 0.82rem); line-height: 1.75;
  color: #b9c6d6; padding: 1.2rem 1.25rem; height: 360px; overflow: hidden; white-space: pre-wrap; word-break: break-all;
}
.terminal-body .p { color: #33e39b; }
.terminal-body .c { color: #6b7a90; }
.terminal-body .ok { color: #33e39b; font-weight: 700; }
.terminal-body .w { color: #ffc857; }
.terminal-body .h { color: #7cc7ff; }
.cursor { display: inline-block; width: 0.55em; height: 1.1em; background: #33e39b; vertical-align: text-bottom; animation: blink 1s steps(1) infinite; }
@keyframes blink { 50% { opacity: 0; } }


.stats {
  margin-top: clamp(3rem, 7vw, 5.5rem);
  display: grid; grid-template-columns: repeat(4, 1fr);
  border: 1px solid var(--border); border-radius: var(--radius-lg); background: var(--surface); overflow: hidden;
}
.stat { padding: var(--space-6) var(--space-6); border-right: 1px solid var(--border); display: flex; flex-direction: column-reverse; gap: 0.3rem; }
.stat:last-child { border-right: 0; }
.stat dt { font-size: var(--text-xs); color: var(--text-muted); text-transform: uppercase; letter-spacing: 0.08em; }
.stat dd { font-family: var(--font-mono); font-size: var(--text-xl); font-weight: 700; color: var(--text); font-variant-numeric: tabular-nums; }


.section { padding-block: clamp(4rem, 9vw, 7.5rem); position: relative; }
.section-alt { background: color-mix(in srgb, var(--surface) 55%, transparent); border-block: 1px solid var(--border); }
.section-head { max-width: 680px; margin-bottom: clamp(2.5rem, 5vw, 4rem); }
.section-head h2 { font-size: var(--text-2xl); margin-bottom: var(--space-4); }
.section-head p:not(.kicker) { color: var(--text-muted); font-size: var(--text-lg); }
.kicker { font-family: var(--font-mono); font-size: var(--text-xs); color: var(--accent); letter-spacing: 0.08em; margin-bottom: var(--space-4); text-transform: uppercase; }


.card {
  background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius-lg);
  padding: var(--space-6); position: relative;
  transition: border-color var(--t-med), transform var(--t-med) var(--ease), box-shadow var(--t-med), background var(--t-med);
}
.services-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: var(--space-4); }
.service { display: flex; flex-direction: column; gap: var(--space-3); overflow: hidden; }
.service::before {
  content: ''; position: absolute; inset: 0; border-radius: inherit; pointer-events: none;
  background: radial-gradient(400px circle at var(--mx, 50%) var(--my, 0%), var(--accent-soft), transparent 45%);
  opacity: 0; transition: opacity var(--t-med);
}
.service:hover { border-color: color-mix(in srgb, var(--accent) 45%, var(--border)); transform: translateY(-3px); box-shadow: var(--shadow); }
.service:hover::before { opacity: 1; }
.card-icon { width: 44px; height: 44px; border-radius: var(--radius-md); display: grid; place-items: center; background: var(--accent-soft); color: var(--accent); border: 1px solid color-mix(in srgb, var(--accent) 25%, transparent); margin-bottom: var(--space-2); }
.card-icon svg { width: 22px; height: 22px; }
.service h3 { font-size: var(--text-lg); }
.service p { font-size: var(--text-sm); color: var(--text-muted); flex: 1; }
.tags { display: flex; flex-wrap: wrap; gap: 0.35rem; margin-top: var(--space-2); }
.tags li { font-family: var(--font-mono); font-size: 0.68rem; color: var(--text-muted); background: var(--surface-2); border: 1px solid var(--border); padding: 0.15rem 0.5rem; border-radius: var(--radius-sm); }


.timeline { display: grid; grid-template-columns: repeat(5, 1fr); gap: var(--space-4); counter-reset: step; position: relative; }
.timeline::before { content: ''; position: absolute; top: 22px; left: 22px; right: 22px; height: 1px; background: linear-gradient(90deg, var(--accent), var(--border-strong) 60%, transparent); }
.step { display: flex; flex-direction: column; gap: var(--space-4); position: relative; }
.step-num {
  width: 44px; height: 44px; display: grid; place-items: center; border-radius: 50%;
  font-family: var(--font-mono); font-weight: 700; font-size: var(--text-sm);
  background: var(--bg); border: 1px solid var(--accent); color: var(--accent); position: relative; z-index: 1;
  box-shadow: 0 0 0 6px var(--bg);
}
.section-alt .step-num { box-shadow: 0 0 0 6px color-mix(in srgb, var(--surface) 55%, var(--bg)); }
.step h3 { font-size: var(--text-lg); margin-bottom: var(--space-2); }
.step p { font-size: var(--text-sm); color: var(--text-muted); }


.hash-wrap { display: grid; grid-template-columns: 0.9fr 1.1fr; gap: clamp(2rem, 5vw, 4rem); align-items: center; }
.hash-copy h2 { font-size: var(--text-2xl); margin-bottom: var(--space-4); }
.hash-copy p { color: var(--text-muted); margin-bottom: var(--space-4); font-size: var(--text-lg); }
.hash-copy strong { color: var(--text); }
.hash-copy .muted { font-size: var(--text-sm); }
.hash-tool { display: flex; flex-direction: column; gap: var(--space-5); padding: var(--space-6); }
.dropzone {
  border: 1.5px dashed var(--border-strong); border-radius: var(--radius-md); padding: var(--space-8) var(--space-4);
  display: flex; flex-direction: column; align-items: center; gap: var(--space-2); text-align: center; cursor: pointer;
  background: var(--surface-2); transition: border-color var(--t-fast), background var(--t-fast);
}
.dropzone svg { width: 32px; height: 32px; color: var(--accent); margin-bottom: var(--space-2); }
.dropzone:hover, .dropzone.drag { border-color: var(--accent); background: var(--accent-soft); }
.dropzone:focus-within { outline: 2px solid var(--accent); outline-offset: 3px; }
.dz-title { font-weight: 700; }
.dz-sub { font-family: var(--font-mono); font-size: var(--text-xs); color: var(--text-faint); }
.hash-result { display: flex; flex-direction: column; border: 1px solid var(--border); border-radius: var(--radius-md); overflow: hidden; }
.hash-row { display: grid; grid-template-columns: 90px 1fr; gap: var(--space-3); padding: 0.7rem 1rem; border-bottom: 1px solid var(--border); font-size: var(--text-sm); }
.hash-row:last-child { border-bottom: 0; }
.hash-label { font-family: var(--font-mono); font-size: var(--text-xs); color: var(--text-faint); text-transform: uppercase; letter-spacing: 0.06em; padding-top: 2px; }
.hash-value { overflow-wrap: anywhere; min-width: 0; }
.hash-code { font-family: var(--font-mono); font-size: 0.78rem; color: var(--accent); }
.compare-row { display: flex; gap: var(--space-2); }
.compare-row .input { flex: 1; min-width: 0; font-size: 0.8rem; }
.compare-status { font-family: var(--font-mono); font-size: var(--text-xs); margin-top: var(--space-2); min-height: 1.2em; }
.compare-status.match { color: var(--accent); }
.compare-status.nomatch { color: var(--danger); }


.cases-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: var(--space-4); }
.case { display: flex; flex-direction: column; gap: var(--space-3); }
.case:hover { border-color: var(--border-strong); transform: translateY(-3px); }
.case-meta { display: flex; align-items: center; gap: var(--space-3); font-family: var(--font-mono); font-size: var(--text-xs); color: var(--text-muted); }
.pill { background: var(--accent-soft); color: var(--accent); padding: 0.15rem 0.55rem; border-radius: 999px; border: 1px solid color-mix(in srgb, var(--accent) 30%, transparent); }
.case h3 { font-size: var(--text-lg); }
.case > p:not(.case-meta):not(.case-result) { color: var(--text-muted); font-size: var(--text-sm); flex: 1; }
.case-result { border-top: 1px solid var(--border); padding-top: var(--space-3); font-weight: 700; font-size: var(--text-sm); display: flex; flex-direction: column; gap: 0.15rem; }
.case-result span { font-family: var(--font-mono); font-weight: 400; font-size: var(--text-xs); color: var(--text-faint); text-transform: uppercase; letter-spacing: 0.06em; }


.faq-wrap { max-width: 860px; }
.faq-list { display: flex; flex-direction: column; gap: var(--space-3); }
.faq { border: 1px solid var(--border); border-radius: var(--radius-md); background: var(--surface); transition: border-color var(--t-fast); }
.faq[open] { border-color: color-mix(in srgb, var(--accent) 40%, var(--border)); }
.faq summary {
  list-style: none; cursor: pointer; padding: var(--space-5) var(--space-6); font-weight: 700;
  display: flex; justify-content: space-between; align-items: center; gap: var(--space-4);
}
.faq summary::-webkit-details-marker { display: none; }
.faq summary::after { content: '+'; font-family: var(--font-mono); font-size: 1.3rem; color: var(--accent); transition: transform var(--t-med) var(--ease); flex-shrink: 0; }
.faq[open] summary::after { transform: rotate(45deg); }
.faq p { padding: 0 var(--space-6) var(--space-5); color: var(--text-muted); font-size: var(--text-sm); max-width: 70ch; }


.contact-wrap { display: grid; grid-template-columns: 0.9fr 1.1fr; gap: clamp(2rem, 5vw, 4.5rem); align-items: start; }
.contact-copy h2 { font-size: var(--text-2xl); margin-bottom: var(--space-4); }
.contact-copy > p { color: var(--text-muted); font-size: var(--text-lg); margin-bottom: var(--space-8); }
.contact-list { display: flex; flex-direction: column; gap: var(--space-4); margin-bottom: var(--space-6); }
.contact-list li { display: flex; flex-direction: column; gap: 0.15rem; padding-left: var(--space-4); border-left: 2px solid var(--accent); }
.cl-label { font-family: var(--font-mono); font-size: var(--text-xs); color: var(--text-faint); text-transform: uppercase; letter-spacing: 0.06em; }
.contact-list a { font-weight: 700; transition: color var(--t-fast); }
.contact-list a:hover { color: var(--accent); }
.pgp { font-size: 0.7rem; color: var(--text-faint); word-break: break-word; }

.contact-form { display: flex; flex-direction: column; gap: var(--space-4); padding: clamp(1.25rem, 3vw, 2rem); }
.field { display: flex; flex-direction: column; gap: 0.4rem; }
.field-row { display: grid; grid-template-columns: 1fr 1fr; gap: var(--space-4); }
.field-label { font-size: var(--text-xs); font-weight: 700; color: var(--text-muted); text-transform: uppercase; letter-spacing: 0.06em; }
.input {
  width: 100%; padding: 0.8rem 0.95rem; border-radius: var(--radius-md);
  border: 1px solid var(--border-strong); background: var(--surface-2); color: var(--text);
  transition: border-color var(--t-fast), box-shadow var(--t-fast), background var(--t-fast);
}
.input::placeholder { color: var(--text-faint); }
.input:focus { outline: none; border-color: var(--accent); box-shadow: 0 0 0 3px var(--accent-soft); background: var(--surface); }
.input.invalid { border-color: var(--danger); }
textarea.input { resize: vertical; min-height: 120px; }
select.input { appearance: none; -webkit-appearance: none; background-image: linear-gradient(45deg, transparent 50%, var(--text-muted) 50%), linear-gradient(135deg, var(--text-muted) 50%, transparent 50%); background-position: calc(100% - 20px) 50%, calc(100% - 15px) 50%; background-size: 5px 5px; background-repeat: no-repeat; padding-right: 2.5rem; }
.field-hint { font-size: var(--text-xs); color: var(--text-faint); font-family: var(--font-mono); }
.field-error { font-size: var(--text-xs); color: var(--danger); min-height: 0; }
.field-error:empty { display: none; }
.check { display: flex; gap: 0.7rem; align-items: flex-start; font-size: var(--text-sm); color: var(--text-muted); cursor: pointer; }
.check input { width: 18px; height: 18px; margin-top: 3px; accent-color: var(--accent); flex-shrink: 0; }
.hp { position: absolute !important; left: -9999px !important; width: 1px; height: 1px; overflow: hidden; }
.form-status { font-family: var(--font-mono); font-size: var(--text-xs); text-align: center; min-height: 1.2em; }
.form-status.ok { color: var(--accent); }
.form-status.err { color: var(--danger); }


.site-footer { border-top: 1px solid var(--border); padding-block: var(--space-12); }
.footer-inner { display: grid; grid-template-columns: 1.3fr 1fr 1fr; gap: var(--space-8); align-items: start; }
.footer-brand .brand-text { margin-bottom: var(--space-3); }
.footer-brand p { font-size: var(--text-sm); max-width: 38ch; }
.footer-nav { display: flex; flex-wrap: wrap; gap: var(--space-3) var(--space-6); font-size: var(--text-sm); color: var(--text-muted); }
.footer-nav a:hover { color: var(--accent); }
.footer-legal { font-size: var(--text-xs); color: var(--text-faint); justify-self: end; text-align: right; }

.to-top {
  position: fixed; right: 1.25rem; bottom: 1.25rem; z-index: 90; width: 44px; height: 44px; border-radius: var(--radius-md);
  background: var(--surface); border: 1px solid var(--border-strong); color: var(--accent); font-size: 1.1rem; font-weight: 700;
  opacity: 0; transform: translateY(12px); pointer-events: none; transition: opacity var(--t-med), transform var(--t-med) var(--ease), border-color var(--t-fast);
}
.to-top.show { opacity: 1; transform: none; pointer-events: auto; }
.to-top:hover { border-color: var(--accent); }


.reveal { opacity: 0; transform: translateY(18px); transition: opacity 0.7s var(--ease), transform 0.7s var(--ease); }
.reveal.visible { opacity: 1; transform: none; }
.no-js .reveal { opacity: 1; transform: none; }


@media (max-width: 1080px) {
  .services-grid { grid-template-columns: repeat(2, 1fr); }
  .timeline { grid-template-columns: 1fr; gap: var(--space-6); }
  .timeline::before { top: 22px; bottom: 22px; left: 22px; right: auto; width: 1px; height: auto; background: linear-gradient(180deg, var(--accent), var(--border-strong) 70%, transparent); }
  .step { flex-direction: row; align-items: flex-start; gap: var(--space-5); }
  .step-num { flex-shrink: 0; }
}

@media (max-width: 900px) {
  .menu-toggle { display: flex; }
  .main-nav {
    position: fixed; top: var(--header-h); left: 0; right: 0; bottom: 0;
    flex-direction: column; align-items: stretch; justify-content: flex-start; gap: var(--space-6);
    padding: var(--space-8) 1.25rem; background: var(--bg); border-top: 1px solid var(--border);
    transform: translateX(100%); visibility: hidden; transition: transform var(--t-med) var(--ease), visibility var(--t-med);
    overflow-y: auto;
  }
  .main-nav.open { transform: none; visibility: visible; }
  .main-nav ul { flex-direction: column; gap: 0; }
  .main-nav ul a { display: block; font-size: var(--text-xl); font-weight: 700; color: var(--text); padding-block: var(--space-4); border-bottom: 1px solid var(--border); }
  .main-nav ul a::after { display: none; }
  .nav-cta { padding: 1rem; font-size: var(--text-base); }

  .hero-inner, .hash-wrap, .contact-wrap { grid-template-columns: 1fr; }
  .terminal-body { height: 300px; }
  .stats { grid-template-columns: repeat(2, 1fr); }
  .stat:nth-child(2) { border-right: 0; }
  .stat:nth-child(-n+2) { border-bottom: 1px solid var(--border); }
  .cases-grid { grid-template-columns: 1fr; }
  .footer-inner { grid-template-columns: 1fr; }
  .footer-legal { justify-self: start; text-align: left; }
}

@media (max-width: 560px) {
  :root { --header-h: 64px; }
  .services-grid { grid-template-columns: 1fr; }
  .field-row { grid-template-columns: 1fr; }
  .hero-ctas .btn { flex: 1 1 100%; }
  .stat { padding: var(--space-4); }
  .brand-sub { display: none; }
  .compare-row { flex-direction: column; }
  .hash-row { grid-template-columns: 1fr; gap: 0.2rem; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: 0.01ms !important; animation-iteration-count: 1 !important; transition-duration: 0.01ms !important; scroll-behavior: auto !important; }
  .reveal { opacity: 1; transform: none; }
  .bg-matrix { display: none; }
}

@media print {
  .site-header, .bg-grid, .bg-matrix, .to-top, .terminal, .hash-tool { display: none !important; }
  body { background: #fff; color: #000; }
}


.blog-posts-area .post-outer, .blog-posts-area .post { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius-lg); padding: var(--space-6); margin-bottom: var(--space-4); }
.blog-posts-area .post-title, .blog-posts-area h3.post-title { font-size: var(--text-lg); margin-bottom: var(--space-3); }
.blog-posts-area .post-title a:hover { color: var(--accent); }
.blog-posts-area .post-body, .blog-posts-area .snippet-item { color: var(--text-muted); font-size: var(--text-sm); }
.blog-posts-area img { border-radius: var(--radius-md); height: auto; }
.blog-posts-area a { color: var(--accent); }
.blog-pager { display: flex; justify-content: space-between; margin-top: var(--space-6); font-family: var(--font-mono); font-size: var(--text-sm); }
#navbar, .navbar, #Navbar1 { display: none !important; }
body .widget { margin: 0; }

body.script:
//
/* ==========================================================
   VESTIGIO \u00b7 Inform\u00e1tica Forense
   L\u00f3gica de interfaz + medidas de seguridad del lado cliente
   ========================================================== */
(function () {
  'use strict';

  var doc = document;
  var root = doc.documentElement;
  var $ = function (sel, ctx) { return (ctx || doc).querySelector(sel); };
  var $$ = function (sel, ctx) { return Array.prototype.slice.call((ctx || doc).querySelectorAll(sel)); };
  var reduceMotion = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  /* ---------- Seguridad: enlaces externos sin acceso a window.opener ---------- */
  $$('a[href^="http"]').forEach(function (a) {
    if (a.hostname !== window.location.hostname) {
      a.setAttribute('target', '_blank');
      a.setAttribute('rel', 'noopener noreferrer');
    }
  });

  /* ---------- Tema claro / oscuro ---------- */
  var themeBtn = $('#theme-toggle');
  var metaTheme = $('meta[name="theme-color"]');
  function applyTheme(t) {
    root.setAttribute('data-theme', t);
    if (themeBtn) themeBtn.setAttribute('aria-label', t === 'dark' ? 'Cambiar a tema claro' : 'Cambiar a tema oscuro');
    if (metaTheme) metaTheme.setAttribute('content', t === 'dark' ? '#07090d' : '#f4f6f8');
  }
  applyTheme(root.getAttribute('data-theme') === 'light' ? 'light' : 'dark');
  if (themeBtn) {
    themeBtn.addEventListener('click', function () {
      applyTheme(root.getAttribute('data-theme') === 'dark' ? 'light' : 'dark');
    });
  }

  /* ---------- Men\u00fa m\u00f3vil ---------- */
  var menuBtn = $('#menu-toggle');
  var nav = $('#main-nav');
  function closeMenu() {
    if (!nav) return;
    nav.classList.remove('open');
    menuBtn.setAttribute('aria-expanded', 'false');
    menuBtn.setAttribute('aria-label', 'Abrir men\u00fa');
    doc.body.style.overflow = '';
  }
  if (menuBtn && nav) {
    menuBtn.addEventListener('click', function () {
      var open = nav.classList.toggle('open');
      menuBtn.setAttribute('aria-expanded', String(open));
      menuBtn.setAttribute('aria-label', open ? 'Cerrar men\u00fa' : 'Abrir men\u00fa');
      doc.body.style.overflow = open ? 'hidden' : '';
    });
    $$('a', nav).forEach(function (a) { a.addEventListener('click', closeMenu); });
    doc.addEventListener('keydown', function (e) { if (e.key === 'Escape') closeMenu(); });
    window.addEventListener('resize', function () { if (window.innerWidth > 900) closeMenu(); });
  }

  /* ---------- Header con scroll + bot\u00f3n subir + enlace activo ---------- */
  var header = $('.site-header');
  var toTop = $('#to-top');
  var navLinks = $$('.main-nav ul a');
  var sections = navLinks.map(function (a) { return $(a.getAttribute('href')); }).filter(Boolean);
  var ticking = false;
  function onScroll() {
    var y = window.scrollY;
    if (header) header.classList.toggle('scrolled', y > 10);
    if (toTop) toTop.classList.toggle('show', y > 700);
    var current = null;
    sections.forEach(function (s) { if (s.getBoundingClientRect().top < window.innerHeight * 0.35) current = s; });
    navLinks.forEach(function (a) { a.classList.toggle('active', current && a.getAttribute('href') === '#' + current.id); });
    ticking = false;
  }
  window.addEventListener('scroll', function () {
    if (!ticking) { window.requestAnimationFrame(onScroll); ticking = true; }
  }, { passive: true });
  onScroll();
  if (toTop) toTop.addEventListener('click', function () { window.scrollTo({ top: 0, behavior: reduceMotion ? 'auto' : 'smooth' }); });

  /* ---------- Revelado al hacer scroll ---------- */
  var reveals = $$('.reveal');
  if ('IntersectionObserver' in window && !reduceMotion) {
    var io = new IntersectionObserver(function (entries) {
      entries.forEach(function (en) {
        if (en.isIntersecting) { en.target.classList.add('visible'); io.unobserve(en.target); }
      });
    }, { threshold: 0.12, rootMargin: '0px 0px -40px 0px' });
    reveals.forEach(function (el, i) {
      el.style.transitionDelay = (i % 4) * 70 + 'ms';
      io.observe(el);
    });
  } else {
    reveals.forEach(function (el) { el.classList.add('visible'); });
  }

  /* ---------- Contadores ---------- */
  var counters = $$('.counter');
  function animateCounter(el) {
    var target = parseInt(el.getAttribute('data-target'), 10) || 0;
    if (reduceMotion) { el.textContent = target.toLocaleString('es-CO'); return; }
    var start = null, dur = 1600;
    function step(ts) {
      if (!start) start = ts;
      var p = Math.min((ts - start) / dur, 1);
      var eased = 1 - Math.pow(1 - p, 3);
      el.textContent = Math.round(target * eased).toLocaleString('es-CO');
      if (p < 1) window.requestAnimationFrame(step);
    }
    window.requestAnimationFrame(step);
  }
  if ('IntersectionObserver' in window) {
    var co = new IntersectionObserver(function (entries) {
      entries.forEach(function (en) { if (en.isIntersecting) { animateCounter(en.target); co.unobserve(en.target); } });
    }, { threshold: 0.6 });
    counters.forEach(function (c) { co.observe(c); });
  } else { counters.forEach(animateCounter); }

  /* ---------- Brillo que sigue al cursor en tarjetas ---------- */
  $$('.service').forEach(function (card) {
    card.addEventListener('pointermove', function (e) {
      var r = card.getBoundingClientRect();
      card.style.setProperty('--mx', (e.clientX - r.left) + 'px');
      card.style.setProperty('--my', (e.clientY - r.top) + 'px');
    });
  });

  /* ---------- Terminal animada (sin innerHTML con datos externos) ---------- */
  var term = $('#terminal-body');
  var script = [
    [['p', '$ '], ['', 'lsblk -o NAME,SIZE,MODEL /dev/sdb']],
    [['c', 'sdb  476.9G  Samsung SSD 860 EVO']],
    [['p', '$ '], ['', 'wblock --enable /dev/sdb']],
    [['ok', '[OK] '], ['', 'Bloqueador de escritura activo']],
    [['p', '$ '], ['', 'dc3dd if=/dev/sdb hof=caso0417.e01 hash=sha256']],
    [['c', '512000 MB copiados \u00b7 0 errores \u00b7 00:41:07']],
    [['h', 'sha256 src  '], ['', '9f2c4e1a7b...d03e88']],
    [['h', 'sha256 img  '], ['', '9f2c4e1a7b...d03e88']],
    [['ok', '[OK] '], ['', 'Integridad verificada \u00b7 hashes coinciden']],
    [['p', '$ '], ['', 'custodia --sellar caso0417 --perito JF-042']],
    [['w', '[!]  '], ['', 'Registro firmado 2026-09-25T14:03:11-05:00']],
    [['ok', '[OK] '], ['', 'Evidencia lista para an\u00e1lisis']]
  ];
  function renderStatic() {
    term.textContent = '';
    script.forEach(function (line) {
      line.forEach(function (seg) {
        var s = doc.createElement('span');
        if (seg[0]) s.className = seg[0];
        s.textContent = seg[1];
        term.appendChild(s);
      });
      term.appendChild(doc.createTextNode('\n'));
    });
  }
  if (term) {
    if (reduceMotion) { renderStatic(); }
    else {
      var cursor = doc.createElement('span');
      cursor.className = 'cursor';
      var li = 0, si = 0, ci = 0, span = null;
      var typeLine = function () {
        if (li >= script.length) {
          term.appendChild(cursor);
          window.setTimeout(function () { term.textContent = ''; li = 0; si = 0; ci = 0; span = null; typeLine(); }, 5200);
          return;
        }
        var line = script[li];
        var seg = line[si];
        var isCmd = line[0][0] === 'p' && si === 1;
        if (!span) {
          span = doc.createElement('span');
          if (seg[0]) span.className = seg[0];
          term.appendChild(span);
          term.appendChild(cursor);
        }
        if (isCmd && ci < seg[1].length) {
          span.textContent += seg[1].charAt(ci++);
          window.setTimeout(typeLine, 18 + Math.random() * 40);
          return;
        }
        if (!isCmd) span.textContent = seg[1];
        si++; ci = 0; span = null;
        if (si >= line.length) {
          term.insertBefore(doc.createTextNode('\n'), cursor);
          li++; si = 0;
          window.setTimeout(typeLine, isCmd ? 380 : 140);
        } else { typeLine(); }
      };
      typeLine();
    }
  }

  /* ---------- Lluvia de caracteres (canvas) ---------- */
  var canvas = $('#matrix');
  if (canvas && canvas.getContext && !reduceMotion) {
    var ctx = canvas.getContext('2d');
    var chars = '01ABCDEF#$%<>/{}[]'.split('');
    var fontSize = 14, cols = 0, drops = [], w = 0, h = 0, last = 0;
    var resize = function () {
      var dpr = Math.min(window.devicePixelRatio || 1, 2);
      w = window.innerWidth; h = window.innerHeight;
      canvas.width = w * dpr; canvas.height = h * dpr;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      cols = Math.floor(w / fontSize);
      drops = [];
      for (var i = 0; i < cols; i++) drops[i] = Math.random() * -50;
    };
    var draw = function (ts) {
      if (doc.hidden) { window.requestAnimationFrame(draw); return; }
      if (ts - last > 60) {
        last = ts;
        var rgb = getComputedStyle(root).getPropertyValue('--matrix-color').trim() || '51, 227, 155';
        var bg = getComputedStyle(root).getPropertyValue('--bg').trim() || '#07090d';
        ctx.globalAlpha = 0.12; ctx.fillStyle = bg; ctx.fillRect(0, 0, w, h);
        ctx.globalAlpha = 1; ctx.fillStyle = 'rgb(' + rgb + ')';
        ctx.font = fontSize + 'px JetBrains Mono, monospace';
        for (var i = 0; i < cols; i++) {
          ctx.fillText(chars[(Math.random() * chars.length) | 0], i * fontSize, drops[i] * fontSize);
          if (drops[i] * fontSize > h && Math.random() > 0.975) drops[i] = 0;
          drops[i] += 1;
        }
      }
      window.requestAnimationFrame(draw);
    };
    resize();
    window.addEventListener('resize', resize);
    window.requestAnimationFrame(draw);
  }

  /* ---------- Verificador SHA-256 local ---------- */
  var fileInput = $('#hash-file');
  var dropzone = $('#dropzone');
  var hashOut = $('#hash-out'), hashName = $('#hash-name'), hashSize = $('#hash-size');
  var expected = $('#hash-expected'), compareStatus = $('#compare-status'), copyBtn = $('#hash-copy');
  var currentHash = '';
  var MAX_BYTES = 200 * 1024 * 1024;

  function fmtBytes(b) {
    var u = ['B', 'KB', 'MB', 'GB']; var i = 0;
    while (b >= 1024 && i < u.length - 1) { b /= 1024; i++; }
    return b.toFixed(i ? 2 : 0) + ' ' + u[i];
  }
  function compare() {
    var v = (expected.value || '').trim().toLowerCase().replace(/[^a-f0-9]/g, '');
    compareStatus.className = 'compare-status';
    if (!v || !currentHash) { compareStatus.textContent = ''; return; }
    if (v.length !== 64) { compareStatus.textContent = 'Un SHA-256 tiene 64 caracteres hexadecimales (' + v.length + '/64).'; return; }
    if (v === currentHash) { compareStatus.textContent = '\u2714 Coincide \u00b7 integridad verificada'; compareStatus.classList.add('match'); }
    else { compareStatus.textContent = '\u2716 No coincide \u00b7 el archivo pudo ser alterado'; compareStatus.classList.add('nomatch'); }
  }
  function handleFile(file) {
    if (!file) return;
    hashName.textContent = file.name.slice(0, 120);
    hashSize.textContent = fmtBytes(file.size);
    currentHash = ''; copyBtn.disabled = true;
    if (file.size > MAX_BYTES) { hashOut.textContent = 'Archivo demasiado grande para el navegador (m\u00e1x. 200 MB).'; return; }
    if (!window.crypto || !window.crypto.subtle) { hashOut.textContent = 'Su navegador no soporta Web Crypto (requiere HTTPS).'; return; }
    hashOut.textContent = 'Calculando\u2026';
    file.arrayBuffer().then(function (buf) {
      return window.crypto.subtle.digest('SHA-256', buf);
    }).then(function (digest) {
      currentHash = Array.prototype.map.call(new Uint8Array(digest), function (b) { return ('0' + b.toString(16)).slice(-2); }).join('');
      hashOut.textContent = currentHash;
      copyBtn.disabled = false;
      compare();
    }).catch(function () { hashOut.textContent = 'No se pudo leer el archivo.'; });
  }
  if (fileInput && dropzone) {
    fileInput.addEventListener('change', function () { handleFile(fileInput.files[0]); });
    ['dragenter', 'dragover'].forEach(function (ev) {
      dropzone.addEventListener(ev, function (e) { e.preventDefault(); dropzone.classList.add('drag'); });
    });
    ['dragleave', 'drop'].forEach(function (ev) {
      dropzone.addEventListener(ev, function (e) { e.preventDefault(); dropzone.classList.remove('drag'); });
    });
    dropzone.addEventListener('drop', function (e) { if (e.dataTransfer && e.dataTransfer.files.length) handleFile(e.dataTransfer.files[0]); });
    expected.addEventListener('input', compare);
    copyBtn.addEventListener('click', function () {
      if (!currentHash || !navigator.clipboard) return;
      navigator.clipboard.writeText(currentHash).then(function () {
        copyBtn.textContent = 'Copiado';
        window.setTimeout(function () { copyBtn.textContent = 'Copiar'; }, 1600);
      });
    });
  }

  /* ---------- Formulario: validaci\u00f3n, saneamiento y antispam ---------- */
  var form = $('#contact-form');
  if (form) {
    var status = $('#form-status');
    var submitBtn = $('#f-submit');
    var msg = $('#f-msg');
    var msgCount = $('#msg-count');
    var loadedAt = Date.now();
    var lastSubmit = 0;
    var RATE_MS = 60 * 1000;

    // Elimina etiquetas, caracteres de control y espacios sobrantes
    var sanitize = function (str, max) {
      return String(str || '')
        .replace(/<[^>]*>/g, '')
        .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, '')
        .replace(/[<>]/g, '')
        .replace(/\s{3,}/g, '  ')
        .trim()
        .slice(0, max);
    };
    var rules = {
      'f-name': function (v) { return v.length >= 3 && /^[\p{L}\s.'-]+$/u.test(v) ? '' : 'Ingrese un nombre v\u00e1lido (solo letras).'; },
      'f-email': function (v) { return /^[^\s@]{1,64}@[^\s@]{1,190}\.[a-z]{2,}$/i.test(v) ? '' : 'Ingrese un correo v\u00e1lido.'; },
      'f-phone': function (v) { return !v || /^[+\d\s()-]{7,20}$/.test(v) ? '' : 'Tel\u00e9fono no v\u00e1lido.'; },
      'f-service': function (v) { return v ? '' : 'Seleccione un servicio.'; },
      'f-msg': function (v) { return v.length >= 20 ? '' : 'Describa el caso con al menos 20 caracteres.'; }
    };
    var showError = function (input, text) {
      var err = input.parentNode.querySelector('.field-error');
      input.classList.toggle('invalid', !!text);
      input.setAttribute('aria-invalid', text ? 'true' : 'false');
      if (err) err.textContent = text;
    };
    Object.keys(rules).forEach(function (id) {
      var el = $('#' + id);
      el.addEventListener('blur', function () { showError(el, rules[id](sanitize(el.value, 1500))); });
      el.addEventListener('input', function () { if (el.classList.contains('invalid')) showError(el, rules[id](sanitize(el.value, 1500))); });
    });
    msg.addEventListener('input', function () { msgCount.textContent = String(msg.value.length); });

    form.addEventListener('submit', function (e) {
      e.preventDefault();
      status.className = 'form-status';
      status.textContent = '';

      // Honeypot y env\u00edo demasiado r\u00e1pido => bot
      if ($('#f-web').value !== '' || Date.now() - loadedAt < 3000) {
        status.textContent = 'No se pudo enviar. Intente nuevamente.';
        status.classList.add('err');
        return;
      }
      // L\u00edmite de frecuencia en el cliente (en memoria)
      if (Date.now() - lastSubmit < RATE_MS) {
        status.textContent = 'Espere un minuto antes de enviar otra solicitud.';
        status.classList.add('err');
        return;
      }

      var data = {}, firstInvalid = null;
      Object.keys(rules).forEach(function (id) {
        var el = $('#' + id);
        var clean = sanitize(el.value, id === 'f-msg' ? 1500 : 120);
        var error = rules[id](clean);
        showError(el, error);
        if (error && !firstInvalid) firstInvalid = el;
        data[el.name] = clean;
      });
      var consent = $('#f-consent');
      $('#consent-error').textContent = consent.checked ? '' : 'Debe aceptar la pol\u00edtica de privacidad.';
      if (!consent.checked && !firstInvalid) firstInvalid = consent;
      if (firstInvalid) { firstInvalid.focus(); return; }

      submitBtn.disabled = true;
      submitBtn.textContent = 'Cifrando y enviando\u2026';

      // Sin backend: se abre el cliente de correo con los datos saneados.
      // Para producci\u00f3n reemplace por fetch() a su endpoint HTTPS con token CSRF.
      var body = 'Nombre: ' + data.nombre + '\nCorreo: ' + data.email + '\nTel\u00e9fono: ' + (data.telefono || '-') +
        '\nServicio: ' + data.servicio + '\n\n' + data.mensaje;
      var href = 'mailto:contacto@vestigio.example?subject=' + encodeURIComponent('Solicitud de peritaje \u00b7 ' + data.servicio) +
        '&body=' + encodeURIComponent(body);

      window.setTimeout(function () {
        lastSubmit = Date.now();
        window.location.href = href;
        status.textContent = 'Solicitud preparada. Se abri\u00f3 su cliente de correo para completar el env\u00edo.';
        status.classList.add('ok');
        form.reset();
        msgCount.textContent = '0';
        submitBtn.disabled = false;
        submitBtn.textContent = 'Enviar solicitud cifrada';
      }, 700);
    });
  }

  /* ---------- A\u00f1o din\u00e1mico ---------- */
  var year = $('#year');
  if (year) year.textContent = String(new Date().getFullYear());
})();

